[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            line-height: 1.6;
            color: #1a1a2e;
            background: #f5f7fa;
        }

        .report-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }

        /* Header */
        .report-header {
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: white;
            padding: 50px 40px;
            margin-bottom: 30px;
            border-radius: 12px;
        }

        .report-header h1 {
            font-size: 2.2em;
            font-weight: 700;
            margin-bottom: 10px;
        }

        .report-header .subtitle {
            font-size: 1.1em;
            opacity: 0.85;
            max-width: 700px;
        }

        .report-header .meta {
            margin-top: 20px;
            font-size: 0.9em;
            opacity: 0.7;
        }

        /* KPI Cards */
        .kpi-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
            gap: 20px;
            margin-bottom: 40px;
        }

        .kpi-card {
            background: white;
            border-radius: 10px;
            padding: 25px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.06);
            border-left: 4px solid #3498db;
        }

        .kpi-card.highlight {
            border-left-color: #27ae60;
            background: linear-gradient(135deg, #27ae60 0%, #2ecc71 100%);
            color: white;
        }

        .kpi-label {
            font-size: 0.85em;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: #666;
            margin-bottom: 8px;
        }

        .kpi-card.highlight .kpi-label {
            color: rgba(255,255,255,0.85);
        }

        .kpi-value {
            font-size: 2em;
            font-weight: 700;
            color: #1a1a2e;
        }

        .kpi-card.highlight .kpi-value {
            color: white;
        }

        .kpi-sub {
            font-size: 0.8em;
            color: #888;
            margin-top: 5px;
        }

        .kpi-card.highlight .kpi-sub {
            color: rgba(255,255,255,0.8);
        }

        /* Section Styling */
        .section {
            background: white;
            border-radius: 10px;
            padding: 35px;
            margin-bottom: 25px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.06);
        }

        .section-title {
            font-size: 1.5em;
            font-weight: 700;
            color: #1a1a2e;
            margin-bottom: 25px;
            padding-bottom: 12px;
            border-bottom: 2px solid #3498db;
        }

